-- Phase 4 staging layer: production's columns (read-only catalog query, 2026-10-28) on tables the call, callback, knowledge
-- and assistant-config functions use. Staging only; added with 'if not exists' so the base copy is unchanged otherwise.
create table if not exists public.assignment_rules (business_id uuid not null primary key, mode text not null default 'round_robin', roles text[] not null default array['owner','admin','manager','staff'], unassigned_alert_minutes integer not null default 10, updated_at timestamptz not null default now());
create table if not exists public.rate_limits (key text not null, window_start timestamptz not null, hits integer not null default 0, primary key (key, window_start));
create table if not exists public.platform_alerts (id uuid not null default gen_random_uuid() primary key, kind text not null, severity text not null default 'warning', business_id uuid, title text not null, detail text, meta jsonb not null default '{}'::jsonb, dedupe_key text not null default '', status text not null default 'open', occurrences integer not null default 1, first_seen_at timestamptz not null default now(), last_seen_at timestamptz not null default now(), notified_at timestamptz, acknowledged_by uuid, acknowledged_at timestamptz, resolved_by uuid, resolved_at timestamptz, resolution_note text);
create unique index if not exists platform_alerts_one_open_idx on public.platform_alerts (kind, coalesce(business_id, '00000000-0000-0000-0000-000000000000'::uuid), dedupe_key) where status <> 'resolved';
create table if not exists public.call_insights (id uuid not null default gen_random_uuid() primary key, business_id uuid not null, call_id uuid not null, status text not null default 'pending', attempts integer not null default 0, claimed_at timestamptz, intent text, sentiment text, urgency text, summary text, details jsonb not null default '{}'::jsonb, unresolved jsonb not null default '[]'::jsonb, model text, error text, review_status text not null default 'new', reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz not null default now(), processed_at timestamptz);
create table if not exists public.callback_attempts (id uuid not null default gen_random_uuid() primary key, callback_id uuid not null, business_id uuid not null, attempt_no integer not null, attempted_at timestamptz not null default now(), outcome text not null, provider_ref text, error text, notes text, next_attempt_at timestamptz, initiated_by text not null default 'system');
create table if not exists public.contact_consents (id uuid not null default gen_random_uuid() primary key, business_id uuid not null, customer_id uuid, phone_digits text, email_lower text, channel text not null, purpose text not null default 'marketing', status text not null, source text not null, keyword text, evidence jsonb not null default '{}'::jsonb, recorded_by uuid, recorded_at timestamptz not null default clock_timestamp());
create table if not exists public.industries (id uuid not null default gen_random_uuid() primary key, name text not null, slug text not null, description text, is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.industry_configurations (id uuid not null default gen_random_uuid() primary key, industry_id uuid not null, terminology jsonb not null default '{}'::jsonb, statuses jsonb not null default '{}'::jsonb, features jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.industry_crm_presets (key text not null primary key, match text[] not null, config jsonb not null, updated_at timestamptz not null default now());
create table if not exists public.live_notices (id uuid not null default gen_random_uuid() primary key, business_id uuid not null, kind text not null, message text not null, ends_at timestamptz not null, created_by uuid, cleared_at timestamptz, created_at timestamptz not null default now());
